/* ---------- chat ---------- */
const md=t=>esc(t).split(/```/).map((p,i)=>i%2?`<pre><code>${p.replace(/^\w*\n/,'')}</code></pre>`:p.replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\*\*([^*\n]+)\*\*/g,'<b>$1</b>').replace(/\n/g,'<br>')).join('');
function citedMarkdown(text,sources){
 const list=(sources||[]).filter(x=>x.kind==='web'&&x.citation!=null&&/^https?:\/\//i.test(x.url||''));
 const linked=String(text||'').replace(/\[(\d+)\](?!\()/g,(hit,n)=>{const x=list.find(s=>String(s.citation)===n);if(!x)return hit;const u=encodeURI(x.url).replace(/\)/g,'%29').replace(/\(/g,'%28').replace(/>/g,'%3E');return `[${n}](<${u}>)`});
 return renderStudioMarkdown(linked);
}
function webResearchHTML(m){
 const ev=(m.activities||[]).slice(-4),web=(m.sources||[]).filter(s=>s.kind==='web');
 const activity=ev.length?`<div class="web-activity" aria-live="polite">${ev.map(x=>`<span class="web-activity-item"><i></i>${esc(x.message||x.type||'Web research')}</span>`).join('')}</div>`:'';
 const cards=web.length?`<details class="web-sources"><summary>Sources used (${web.length})</summary><div class="web-source-grid">${web.map(s=>`<article class="web-source"><div class="web-source-title"><span class="web-citation">[${esc(s.citation??'')}]</span><a href="${esc(s.url||'')}" target="_blank" rel="noopener noreferrer">${esc(s.title||s.domain||'Source')}</a></div><div class="web-meta">${esc(s.domain||'')}${s.published_date?' · Published '+esc(s.published_date):''}${s.retrieved_at?' · Retrieved '+esc(s.retrieved_at):''}</div><p>${esc(String(s.snippet||s.content||'').slice(0,520))}</p><span class="web-badge">${s.full?'Full page':'Snippet only'}${s.truncated?' · truncated':''}</span><button type="button" class="btn web-save" data-web-save="${esc(s.sid||'')}">Save to Knowledge Base</button></article>`).join('')}</div></details>`:'';
 return activity+cards;
}
function consumeResearchWire(wire){
 const marker="\x1eEVT:",end="\x1e";let visible='',events=[];
 while(true){const i=wire.indexOf(marker);if(i<0){let keep=0;for(let n=1;n<marker.length;n++)if(wire.endsWith(marker.slice(0,n)))keep=n;visible+=wire.slice(0,wire.length-keep);return{visible,rest:wire.slice(wire.length-keep),events}}
  visible+=wire.slice(0,i);wire=wire.slice(i);const j=wire.indexOf(end,marker.length);if(j<0)return{visible,rest:wire,events};try{events.push(JSON.parse(wire.slice(marker.length,j)))}catch{}wire=wire.slice(j+1)}
}
function msgHTML(m,i){if(m.role==='user'){let n=[];try{n=JSON.parse(m.names||'[]')}catch{}return`<div class="m u" data-web-mode="${esc(m.webMode||'off')}">${n.map(x=>`<span class="chip">📎 ${esc(x)}</span>`).join('')}${n.length?'<br>':''}${esc(m.content)}</div>`}
 return`<div class="m a"><div class="body ${m.err?'err':''}">${citedMarkdown(m.content,m.sources)}${m.err?`<div class="err">⚠️ ${esc(m.err)}</div>`:''}</div>${(m.sources||[]).length?`<div style="margin-top:6px">${m.sources.map((s,j)=>`<span class="chip" style="cursor:pointer" data-a="vsrc:${s.sid}:${s.loc}">[S${j+1}] ${esc(s.title)} · ${s.label} ${s.loc}</span>`).join('')}</div>`:''}${webResearchHTML(m)}<div class="tools"><button class="ib" data-a="copy:${i}" title="Copy">${ic('copy')}</button>${i===S.msgs.length-1&&!S.gen?`<button class="ib" data-a="regen" title="Regenerate">${ic('redo')}</button>`:''}</div></div>`}
function chips(){$('#chips').innerHTML=(S.kb.length?`<div class="mu" style="margin:0 0 6px 4px">📚 Source-only answers from: ${S.kb.map((k,i)=>`<span class="chip">${k.t==='coll'?'📁':'📄'} ${esc(k.name)} <button class="ib" data-a="krmc:${i}" style="padding:0">×</button></span>`).join('')}</div>`:'')+S.att.map((f,i)=>`<span class="chip">${esc(f.name)} · ${fb(f.size)} <button class="ib" data-a="rm:${i}" style="padding:0">×</button></span>`).join('')}
function addFiles(fs){for(const f of fs){if(f.size>50*2**20){$('#ban').textContent=f.name+' exceeds 50 MB';continue}S.att.push(f)}chips()}
function chatView(){syncConversationWebMode();
 $('#main').innerHTML=`<div id="chat" class="${S.msgs.length?'':'empty'}">
 <div id="msgs"><div class="col" id="col">${S.msgs.map(msgHTML).join('')}</div></div><div id="hero">What’s on your mind today?</div>
 <div class="comp"><div class="amodel" id="amodel">${S.model?`Model: ${esc(S.model)} · ${S.ctx} ctx`:`<a href="#" data-a="nav:set" style="color:inherit">No default model — choose one in Settings</a>`}</div><div id="ban">${esc(S.merr||'')}</div><div id="chips"></div>${webModeControlMarkup('chat')}<div class="box"><button class="ib" data-a="attach" title="Attach files" aria-label="Attach files">${ic('plus')}</button><textarea id="inp" rows="1" placeholder="Message Nexora..."></textarea><button class="send" id="sb" data-a="send" type="button" aria-label="Send message" title="Send message">${ic('up')}</button></div>
 <details><summary>Instructions / system prompt</summary><textarea id="sys" class="in">${esc(S.sys)}</textarea></details></div></div>`;
 chips();const inp=$('#inp');inp.focus();
 inp.oninput=()=>{inp.style.height='auto';inp.style.height=Math.min(inp.scrollHeight,220)+'px';inp.style.overflowY=inp.scrollHeight>220?'auto':'hidden'};
 inp.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.keyCode!==229){e.preventDefault();if(!S.gen)send()}};
 inp.onpaste=e=>addFiles([...e.clipboardData.files]);
 $('#sys').oninput=e=>S.sys=e.target.value;
 bindWebModeControls();
 $('#main').ondragover=e=>e.preventDefault();$('#main').ondrop=e=>{e.preventDefault();addFiles([...e.dataTransfer.files])};
 const c=$('#msgs');c.scrollTop=c.scrollHeight}
$('#file').onchange=e=>{addFiles([...e.target.files]);e.target.value=''};
async function send(regen=false){
 const inp=$('#inp'),text=regen?'':inp.value.trim();if(!regen&&!text&&!S.att.length)return;if(!S.model)return $('#ban').textContent='No default model set. Open Settings → Model Configuration.';
 $('#ban').textContent='';if(!S.cid){S.cid=(await api('/api/chats','POST')).id}
 storeConversationWebMode();
 const fd=new FormData(),files=S.att;fd.append('text',text);fd.append('system',S.sys);fd.append('web_mode',S.webMode||'off');fd.append('regenerate',regen);fd.append('kb',JSON.stringify(S.kb.map(k=>({t:k.t,id:k.id}))));files.forEach(f=>fd.append('files',f));
 const hadN=S.msgs.length;if(!regen)S.msgs.push({role:'user',content:text||'Please read the attached file(s) and summarize them.',names:JSON.stringify(files.map(f=>f.name)),webMode:S.webMode||'off'});
 const a={role:'assistant',content:''};S.msgs.push(a);S.att=[];inp.value='';$('#chat').classList.remove('empty');
 const col=$('#col');col.innerHTML=S.msgs.map(msgHTML).join('');$('#sb').innerHTML=ic('stop');
 const body=()=>col.lastElementChild.querySelector('.body'),sc=$('#msgs');S.gen=new AbortController();
 try{
  const csrf=csrfCookie();const res=await fetch(`/api/chats/${S.cid}/send`,{method:'POST',body:fd,signal:S.gen.signal,credentials:'same-origin',headers:csrf?{'X-CSRF-Token':csrf}:{}});
  if(!res.ok){let d={};try{d=await res.json()}catch{}S.msgs.length=hadN;if(!regen){S.att=files;inp.value=text}throw new Error(d.detail||res.status)}
  const hsrc=res.headers.get('X-Sources');if(hsrc)try{a.sources=JSON.parse(atob(hsrc))}catch{}const rd=res.body.getReader(),dec=new TextDecoder();let wire='',visible='';
  for(;;){const{done,value}=await rd.read();if(done)break;wire+=dec.decode(value,{stream:true});const parsed=consumeResearchWire(wire);wire=parsed.rest;visible+=parsed.visible;if(parsed.events.some(ev=>/web_search|web_fetch|searching|fetching|research/i.test(JSON.stringify(ev)))){const wa=$('#web-activity');if(wa)wa.textContent='Web tools active…'}
   for(const ev of parsed.events){if(ev.type==='sources')a.sources=ev.sources||[];else{a.activities=a.activities||[];a.activities.push(ev);a.activities=a.activities.slice(-6)}col.innerHTML=S.msgs.map(msgHTML).join('')}
   const k=visible.indexOf('\x00ERR:');a.content=k<0?visible:visible.slice(0,k);if(k>=0)a.err=visible.slice(k+5);
   const near=sc.scrollHeight-sc.scrollTop-sc.clientHeight<120;body().innerHTML=citedMarkdown(a.content,a.sources)+(a.err?`<div class="err">⚠️ ${esc(a.err)}</div>`:'');if(near)sc.scrollTop=sc.scrollHeight}
  wire+=dec.decode();if(wire){const parsed=consumeResearchWire(wire);visible+=parsed.visible+parsed.rest;wire=''}const k=visible.indexOf('\x00ERR:');a.content=k<0?visible:visible.slice(0,k);if(k>=0)a.err=visible.slice(k+5);body().innerHTML=citedMarkdown(a.content,a.sources)+(a.err?`<div class="err">⚠️ ${esc(a.err)}</div>`:'');
 }catch(e){if(e.name!=='AbortError'){showWebRequestError(e.message);if(!a.content&&S.msgs[S.msgs.length-1]===a)S.msgs.pop()}}
 S.gen=null;const wa=$('#web-activity');if(wa)wa.textContent='';if(S.page==='chat'){const keep=S.cid;await loadChats();if(S.cid===keep)chatViewKeep()}}
function chatViewKeep(){const b=$('#ban')?.textContent,i=$('#inp')?.value;chatView();$('#ban').textContent=b||'';$('#inp').value=i||''}


function modeName(mode){return mode==='search_first'?'Search first':mode==='automatic'?'Automatic':'Off'}
function webModeControlMarkup(id){return `<div class="web-mode-control"><button type="button" class="web-mode-trigger" data-web-mode-trigger aria-haspopup="menu" aria-expanded="false" aria-controls="${id}-web-menu" aria-label="Web Search mode">${ic('globe')}<span>Web Search</span><b class="web-mode-active">${modeName(S.webMode)}</b><span class="web-chevron" aria-hidden="true">⌄</span></button><div class="web-mode-menu" id="${id}-web-menu" role="menu" aria-label="Web Search mode" hidden>${[['off','Off','Local chat only; no web tools are called.'],['search_first','Search first','Searches first and shares relevant results with your model.'],['automatic','Automatic','The model may decide when to use available web tools.']].map(([v,n,d])=>`<button type="button" role="menuitemradio" aria-checked="${S.webMode===v?'true':'false'}" data-web-mode-choice="${v}"><span class="web-check" aria-hidden="true">${S.webMode===v?'✓':''}</span><span class="web-choice-copy"><b>${n}</b><small>${d}</small></span></button>`).join('')}</div><span class="web-live" id="web-activity" aria-live="polite"></span></div>`}
function modeMap(){try{return JSON.parse(localStorage.getItem('nexora.web_mode_by_chat')||'{}')}catch{return {}}}
function storeConversationWebMode(){const id=(S.page==='code'&&window.NexoraCodeWorkspace?.chatId)||S.cid;if(!id)return;const m=modeMap();m[id]=S.webMode;try{localStorage.setItem('nexora.web_mode_by_chat',JSON.stringify(m))}catch{}}
function syncConversationWebMode(){if(!S.cid){S.webMode=S.cfg?.web_mode_default||localStorage.getItem('nexora.web_mode_default')||'off';return}const m=modeMap();if(Object.prototype.hasOwnProperty.call(m,S.cid)){S.webMode=m[S.cid];return}const last=[...(S.msgs||[])].reverse().find(x=>x.role==='user');S.webMode=last?.webMode||last?.web_mode||S.cfg?.web_mode_default||'off'}
function syncWebModeControls(){document.querySelectorAll('.web-mode-control').forEach(root=>{const b=root.querySelector('[data-web-mode-trigger]');if(b){b.querySelector('.web-mode-active').textContent=modeName(S.webMode);b.classList.toggle('is-on',S.webMode!=='off');b.setAttribute('aria-label','Web Search: '+modeName(S.webMode))}root.querySelectorAll('[data-web-mode-choice]').forEach(x=>{const on=x.dataset.webModeChoice===S.webMode;x.setAttribute('aria-checked',on?'true':'false');x.querySelector('.web-check').textContent=on?'✓':''})})}
function bindWebModeControls(){syncWebModeControls()}
function setWebMode(mode){if(!['off','search_first','automatic'].includes(mode))return;S.webMode=mode;storeConversationWebMode();try{localStorage.setItem('nexora.web_mode_default',mode)}catch{}if(S.cfg)S.cfg.web_mode_default=mode;syncWebModeControls();api('/api/settings','PUT',{web_mode_default:mode}).then(c=>{if(S.cfg)S.cfg.web_mode_default=c.web_mode_default}).catch(()=>{const x=document.querySelector('.web-live');if(x)x.textContent='Saved for this conversation; default setting could not be saved.'})}
function showWebRequestError(message){const b=$('#ban');if(!b)return;b.innerHTML=`${esc(message)}${S.webMode!=='off'?` <span class="web-error-actions"><button type="button" data-web-retry>Retry</button><button type="button" data-web-off>Switch to Off</button></span>`:''}`}
document.addEventListener('click',e=>{const t=e.target.closest('[data-web-mode-trigger]');if(t){const m=document.getElementById(t.getAttribute('aria-controls'));const open=t.getAttribute('aria-expanded')==='true';document.querySelectorAll('.web-mode-menu').forEach(x=>x.hidden=true);document.querySelectorAll('[data-web-mode-trigger]').forEach(x=>x.setAttribute('aria-expanded','false'));m.hidden=open;t.setAttribute('aria-expanded',open?'false':'true');if(!open)m.querySelector('[aria-checked="true"]')?.focus();return}const c=e.target.closest('[data-web-mode-choice]');if(c){setWebMode(c.dataset.webModeChoice);const m=c.closest('.web-mode-menu');m.hidden=true;document.querySelector(`[aria-controls="${m.id}"]`)?.setAttribute('aria-expanded','false');return}if(!e.target.closest('.web-mode-control')){document.querySelectorAll('.web-mode-menu').forEach(x=>x.hidden=true);document.querySelectorAll('[data-web-mode-trigger]').forEach(x=>x.setAttribute('aria-expanded','false'))}if(e.target.closest('[data-web-off]')){setWebMode('off');$('#ban').textContent='Web Search is Off. Retry your message to use local chat only.'}if(e.target.closest('[data-web-retry]')){if(!S.gen)send()}});
document.addEventListener('keydown',e=>{const m=e.target.closest('.web-mode-menu');if(!m)return;const xs=[...m.querySelectorAll('[data-web-mode-choice]')],i=xs.indexOf(document.activeElement);if(e.key==='Escape'){m.hidden=true;document.querySelector(`[aria-controls="${m.id}"]`)?.focus();e.preventDefault()}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();xs[(i+(e.key==='ArrowDown'?1:-1)+xs.length)%xs.length]?.focus()}else if(e.key==='Home'){e.preventDefault();xs[0]?.focus()}else if(e.key==='End'){e.preventDefault();xs.at(-1)?.focus()}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-web-save]');if(!b)return;e.preventDefault();const sid=b.dataset.webSave;try{const cols=await api('/api/kb/collections');if(!Array.isArray(cols)||!cols.length){alert('Create a Knowledge Base collection first.');return}let chosen=S.kb.find(x=>x.t==='coll')?.id||'';if(!chosen){const label=prompt('Save this retrieved source to which Knowledge Base collection? Enter its name or ID:\n'+cols.map(x=>x.name+' · '+x.id).join('\n'));if(label===null)return;const match=cols.find(x=>x.id===label.trim()||x.name.toLowerCase()===label.trim().toLowerCase());if(!match){alert('No matching collection.');return}chosen=match.id}b.disabled=true;b.textContent='Saving…';await api(`/api/chats/${S.cid}/sources/${encodeURIComponent(sid)}/save`,'POST',{collection_id:chosen});b.textContent='Saved to Knowledge Base';b.classList.add('saved')}catch(err){alert('Could not save source: '+err.message);b.disabled=false;b.textContent='Save to Knowledge Base'}});
